export function verifyPageURL(o,e){return window.location.origin+window.location.pathname.replace(/\/[^/]*$/,"/verify.html")+"?book="+encodeURIComponent(o||"")+(e?"&v="+encodeURIComponent(e):"")}export function buildProvenance(o){var e=o.bookCode||"",n=String(o.version||"").toLowerCase(),r=Number(o.rows)||0,i=/^[0-9a-f]{12}$/.test(n),t=i?"source: v"+n:"source: unknown";return{line:t+=" - rows: "+r,url:verifyPageURL(e,i?n:""),bookCode:e,version:i?n:"",rows:r}}